import { createTool, Agent } from "@voltagent/core";
import { z } from "zod";
import { openai } from "@ai-sdk/openai";
import fs from "fs";

const get_weather = createTool({
  name: "get_weather",
  description: "Get the current weather in a given location",
  parameters: z.object({
    city: z.string().describe("The name of the city"),
  }),
  execute: async ({ city }) => {
    return { weather: `Sunny in ${city}`, temperature: 22 };
  },
});

const agent = new Agent({
  name: "Weather Agent",
  instructions: "You are a weather assistant.",
  model: openai("gpt-4o-mini"),
  tools: [get_weather],
});

async function main() {
  try {
    const result = await agent.generateText("What is the weather in London?");
    // Save the result to output.json as requested
    fs.writeFileSync("output.json", JSON.stringify(result, null, 2));
    console.log("Output saved to output.json");
  } catch (error) {
    console.error("Error running agent:", error);
    // Even if it fails, try to write something to output.json if possible, 
    // but the prompt says "resulting JSON", which implies success.
    // If it fails due to missing API key, I'll know.
    fs.writeFileSync("output.json", JSON.stringify({ error: error.message }, null, 2));
    process.exit(1);
  }
}

main();

